import json,hashlib,sys
v=json.load(sys.stdin);a=json.loads(v['rule']);b=json.loads(v['labels']);p=a['content_predictions'];assert a['evaluation_labels_loaded'] is False and len(p)==64 and all(k.startswith('content-') for k in p);z=json.dumps(p,sort_keys=True,separators=(',',':'));assert hashlib.sha256(z.encode()).hexdigest()=='514a42afa42e95078a5236fe26171b5f475dbd0a8533e35e2f49fe493e9ccf72';assert set(p)<=set(b);c=sum(p[k]==b[k] for k in p);print(json.dumps({'score':c,'denominator':len(p),'original_prediction_sha256':hashlib.sha256(z.encode()).hexdigest(),'original_stdout_sha256':hashlib.sha256(v['rule'].encode()).hexdigest(),'original_eval_labels_sha256':hashlib.sha256(v['labels'].encode()).hexdigest(),'per_group':{str(g):sum(p[k]==b[k] for k in p if k.startswith('content-'+str(g)+'-')) for g in [0,1]}}))
